  "Toggle": "切り替える",
  "Page settings — {name}": "ページ設定 ― {name}",
  "Publish this page": "このページを公開する",
  "Unpublished pages are left out of exports and publishing (they stay as drafts).": "非公開のページは、書き出しと公開に含まれません（下書きとして残ります）。",
  "Name": "名前",
  "The page's address (e.g. blog becomes {p1}/blog).\nAdd a query like \"blog?tab=news\" to append it to links to this page; inside the page it's available as {tab}.\nInclude [slug], as in \"blog/[slug]\", to create a detail page for each data item.": "ページのアドレスです（例: blog なら {p1}/blog）。\n「blog?tab=news」のようにクエリを付けると、このページへのリンクに付き、ページの中では {tab} として使えます。\n「blog/[slug]」のように [slug] を入れると、データの1件ごとの詳細ページになります。",
  "(Home page)": "（トップページ）",
  "A detail page for each data item": "データの1件ごとの詳細ページ",
  "One design generates a page for each data item (e.g. /{base}/1, /{base}/2 …).\nIn this page's \"When the page opens\" script, fetch one item using {slug} in the URL, or find the item whose field matches {slug} in a list and store it in a variable.": "1つのデザインから、データの1件ごとにページを作ります（例: /{base}/1、/{base}/2 …）。\nこのページのスクリプトの「ページを開いたとき」で、URLに {slug} を入れて1件を取得するか、一覧の中から項目が {slug} と一致する1件を探して、変数に入れてください。",
  "Outer background color": "外側の背景色",
  "The color shown when scrolling past the edge of the page. Uses the body background color if not set.": "ページの端を越えてスクロールしたときに見える色です。未設定のときは、bodyの背景色を使います。",
  "Scripts": "スクリプト",
  "Connect triggers like \"when a button is clicked\" to actions like opening a page or showing an element to make your page interactive.": "「ボタンをクリックしたとき」などのきっかけに、ページを開く・要素を表示するなどの動作をつなぐと、ページに動きを付けられます。",
  "Edit scripts": "スクリプトを編集",
  "Search & sharing (SEO)": "検索・シェア（SEO）",
  "Title": "タイトル",
  "Description": "説明文",
  "A short summary shown in search results and when shared on social media.": "検索結果やSNSでシェアされたときに表示する、短い紹介文です。",
  "Share image (OGP)": "シェア用画像（OGP）",
  "The image shown when a link is shared on social media. Uses the site's default image if not set. 1200×630px is recommended.": "SNSでリンクがシェアされたときに表示する画像です。未設定のときは、サイトの既定の画像を使います。1200×630px をおすすめします。",
  "Hide from search results (Google, etc.)": "Googleなどの検索結果に表示させない",
  "Custom code": "カスタムコード",
  "Page type": "ページの種類",
  "A standard page built from elements on the canvas. Choose \"HTML\" to write this page directly in code.": "キャンバスで要素を組み立てる、標準のページです。「HTML」を選ぶと、このページをコードで直接書けます。",
  "Standard": "通常",
  "Serve hand-written code": "コードを直接書いて配信",
  "Redirect": "リダイレクト",
  "301 redirect to another URL": "別のURLへ301転送",
  "301 redirect target": "301リダイレクト先",
  "Permanently redirects visitors of this page to the destination. Redirect pages can't be edited on the canvas.": "このページにアクセスした人を、転送先へ恒久的に移動させます。リダイレクトのページは、キャンバスで編集できません。",
  "/new-page or https://example.com/...": "/new-page または https://example.com/...",
  "Show an external site (reverse proxy)": "外部サイトを表示（リバースプロキシ）",
  "Shows the external site's content at this URL without changing the address bar. Under the home page (/), this site's pages and files take priority, and only paths with no match are forwarded. If the destination URL contains ? or #, only paths that match this page's URL are forwarded. This can't be combined with a 301 redirect.": "アドレスバーのURLを変えずに、指定した外部のサイトの内容を、このURLで中継して表示します。トップページ（/）の配下では、このサイトのページとファイルを優先し、見つからないパスだけを中継します。転送先のURLに ? か # が含まれる場合は、このページのURLに一致するパスだけを中継します。301リダイレクトとは同時に設定できません。",
  "Load an HTML file": "HTMLファイルを読み込む",
  "Convert HTML to editable elements": "HTMLを変換して読み込む",
  "Convert HTML and assets from ZIP": "HTMLとアセットのZIPを変換して読み込む",
  "Load HTML without converting": "HTMLをそのまま読み込む",
  "Load HTML and assets from ZIP without converting": "HTMLとアセットのZIPをそのまま読み込む",
  "Loads index.html first. Bundled files are uploaded as assets, and paths in the HTML are rewritten automatically.": "index.html を優先して読み込みます。一緒に入っているファイルはアセットとしてアップロードし、HTMLの中のパスを自動で書き換えます。",
  "Loading zip…": "ZIPを読み込み中…",
  "Load a zip of HTML and assets": "HTMLとアセットのZIPを読み込む",
  "HTML code": "HTMLコード",
  "Serves the HTML, including scripts and CSS, as is (Next.js layouts and metadata don't apply to this page).": "scriptやCSSを含むHTMLを、そのまま配信します（このページには、Next.jsのレイアウトやメタデータは適用されません）。",
  "Head code (this page only)": "先頭コード（このページのみ）",
  "Inserted at the start or end of this page's HTML. Use it for page-specific tracking tags, structured data (JSON-LD) and similar code. Set the title and description under \"Search & sharing\".": "このページのHTMLの先頭か末尾に挿入します。このページだけで使う計測のタグや、構造化データ（JSON-LD）などに使います。タイトルと説明文は、「検索・シェア」で設定してください。",
