  "Release here to delete": "ここで離すと削除",
  "Drag a trigger from the left onto this area, choose its element, then attach action blocks below it.": "左の「きっかけ」をここへドラッグし、どの要素のきっかけかを選んでから、その下に動作のブロックをつなげてください。",
  "Example: \"［Button］ When clicked\" {arrow} \"Open ［page］\"": "例: 「［ボタン］クリックしたとき」{arrow}「［ページ］を開く」",
  "To show data, attach \"Set variable ［］ to ［value］\" under \"Fetch data from ［URL］ as ［name］\" to pull out what you need (it runs when the page opens). Choose a variable holding a list in a List element's settings to show each item.": "データを表示するには、「［URL］のデータを取得して［名前］とする」の下に「［値］を変数［］とする」をつなげて、必要な値を取り出します（ページを開いたときに実行されます）。リストの入った変数を、リストの要素の設定で選ぶと、1件ずつ並べて表示します。",
  "Drag to connect and reorder": "ドラッグでつなげる・並べ替え",
  "+click or drag on empty space to multi-select": "+クリック・空き部分のドラッグで複数選択",
  "Select all": "全選択",
  "Undo/redo": "取り消し・やり直し",
  "Scripts that only open a page or URL \"When clicked\" are output as links (a tags).\nStorage uses localStorage, then a cookie for this site only, then memory (cleared when the page closes), whichever is available first.": "「クリックしたとき」にページやURLを開くだけのスクリプトは、リンク（aタグ）として出力します。\nストレージは、localStorage → このサイトだけのクッキー → メモリ（ページを閉じると消える）の順に、使えるところへ保存します。",
  "Delete {menuCount} blocks": "{menuCount}個のブロックを削除",
