  "ID attribute": "ID属性",
  "This element's value can be inserted into data URLs and links as {{attrId}}.": "この要素の値は、{{attrId}} として、データの取得先のURLやリンクに差し込めます。",
  "Used as the anchor for in-page links, and as the name when inserting the value as a {variable}.": "ページの中のリンクのアンカーや、値を {変数} として差し込むときの名前になります。",
  "Anchor / {variable} name": "アンカー・{変数} の名前",
  "The ID \"slug\" conflicts with this page's {slug} variable. Use a different ID.": "ID「slug」は、このページの変数 {slug} と重なっています。別のIDにしてください。",
  "The ID \"{id}\" is used by {n} elements on this page. Variables and anchors won't work correctly, so give each a unique ID.": "ID「{id}」が、このページの{n}個の要素で重なっています。{変数}やアンカーが正しく動かないため、それぞれ別のIDにしてください。",
  "Can't delete while locked": "ロック中は削除できません",
  "Turn into a reusable part for multiple pages (edits to the main component apply everywhere)": "複数のページで使い回せる部品にします（マスターを編集すると、すべての使用箇所に反映されます）",
  "Use this box as a template and repeat it for each data item": "このボックスをお手本にして、データの件数分くり返すリストにします",
  "Component — {name}": "コンポーネント ― {name}",
  "This is an instance of a component. To change its content, edit the main component (changes apply everywhere it's used).": "これはコンポーネントのインスタンスです。中身を変えるには、マスターを編集してください（すべての使用箇所に反映されます）。",
  "list_variant_1\u0004List": "リスト",
  "List": "一覧",
  "The first item is the template card. Type \"{\" in its text and pick a field to apply it to every card.\nSort and filter with the \"Sort\" and \"Filter\" script actions.": "リストの1つ目が、お手本のカードです。カードの中の文字で「{」を入力して項目を選ぶと、すべてのカードに反映されます。\n並べ替えや絞り込みは、スクリプトの「並べ替える」「絞り込む」で行います。",
  "Array · set after the page opens": "配列 · ページを開いてから値が決まる",
  "Array · {length} sample items": "配列 · 見本{length}件",
  "Outer list item · {count} samples": "外側のリストの項目 · 見本{count}件",
  "Array to list": "並べる配列",
  "Select…": "選択してください",
  "{p1} (not an array)": "{p1}（配列になっていません）",
  "Store it in a variable with a script to make it selectable": "スクリプトで変数に入れると選べるようになります",
  "Store data in a variable or split text into an array with a script, and it will appear here": "スクリプトでデータを変数に入れるか、文字列を分解して配列にすると、ここで選べるようになります",
  "Create an array with a script": "スクリプトで配列を作る",
  "Items to show": "表示件数",
  "Meaning (output tag)": "意味付け（出力タグ）",
  "{label} ({value})": "{label}（{value}）",
  "Specify any tag name to output, such as pre or aside": "pre・aside など、出力するタグ名を自由に指定します",
  "Tag name": "タグ名",
  "Outputs a div when empty or when the tag name can't be used": "空欄や使えないタグ名のときは div で出力します",
  "Connect triggers like \"when clicked\" to actions like opening a page or showing an element to make it interactive.": "「クリックしたとき」などのきっかけに、ページを開く・要素を表示するなどの動作をつなぐと、要素に動きを付けられます。",
  "\nA script that only opens a page or URL \"when clicked\" is output as a link (a tag).": "\n「クリックしたとき」にページやURLを開くだけのスクリプトは、リンク（a タグ）として出力されます。",
  "Edit page scripts": "ページのスクリプトを編集",
