  "https:// or {variable}": "https:// または {変数}",
  "Alt text": "代替テキスト",
  "Describe the image (required)": "画像の説明（必須）",
  "No alt text. The pre-publish check will warn about this.": "代替テキストが未設定です。公開前のチェックで警告されます。",
  "Load first (for images visible on page load)": "優先して読み込む（最初に見える画像向け）",
  "Prevent blurry shadows on iPhone (applied when publishing)": "iPhoneで影がぼやけるのを防ぐ（公開時に適用）",
  "Original size: {w} × {h}px": "元のサイズ: {w} × {h}px",
  "Icon — {name}": "アイコン ― {name}",
  "Change the color with Style → Text → Color, and the size with Size.": "色はスタイルの「テキスト → 色」、大きさは「サイズ」で調整できます。",
  "Icon {name}": "アイコン {name}",
  "Form field": "フォーム部品",
  "The ID attribute above becomes the value's name. Write {ID} to insert it into data URLs and more.": "上の「ID属性」が、入力値の名前になります。{ID} と書くと、データの取得先のURLなどに差し込めます。",
  "\nRadio buttons with the same ID form a group where only one can be selected.": "\n同じID属性のラジオボタンは、1つだけを選べるグループになります。",
  "Label": "表示テキスト",
  "Default value": "初期値",
  "Enter text matching an option": "選択肢と同じ文字を入力",
  "Text entered by default": "最初から入力されている文字",
  "Placeholder": "プレースホルダ",
  "Faint text shown when empty": "未入力時に薄く表示される文字",
  "Options (one per line)": "選択肢（1行に1つ）",
  "This field has no ID attribute, so its value won't be submitted.": "ID属性が未設定のため、この欄の値は送信されません。",
  "Enter the URL of a file such as mp4 or mp3. For YouTube, use the YouTube element.": "mp4やmp3などのファイルのURLを指定します。YouTubeの動画には、「YouTube」の要素を使ってください。",
  "File URL": "ファイルURL",
  "(asset video)": "（アセットの動画）",
