  "Embed URL": "URL埋め込み",
  "Sites that don't allow embedding may not appear.": "埋め込みを許可していないサイトは表示されないことがあります。",
  "Video URL": "動画のURL",
  "Address, place name or map URL": "住所・場所名・マップのURL",
  "URL of the page to embed": "埋め込むページのURL",
  "e.g. Eiffel Tower": "例: 東京駅",
  "Couldn't read the URL. Check its format.": "URLを読み取れませんでした。形式を確認してください。",
  "Custom code (HTML)": "カスタムコード（HTML）",
