  "Loading text": "ローディングテキスト",
  "Show a loading screen": "ローディング画面を表示する",
  "Design it on the canvas, just like a regular page.": "通常のページと同じように、キャンバスで要素を追加して編集できます。",
  "Edit loading screen": "ローディング画面を編集",
  "Minimum display time (ms)": "最短の表示時間（ms）",
