  "Show only once per tab": "同じタブでは初回だけ表示する",
  "Standalone": "スタンドアロン",
  "Opens like an app, without the address bar.": "アドレスバーの無い、アプリと同じ見た目で開きます。",
  "Minimal UI": "最小UI",
  "Opens with only minimal controls like back and reload.": "戻る・再読み込みなどの、最小限の操作だけを残して開きます。",
  "Full screen": "全画面",
  "Hides the status bar too and fills the whole screen. Good for games and kiosks.": "ステータスバーも隠し、画面全体に表示します。ゲームや展示に向いています。",
  "Publish as a PWA": "PWAとして公開する",
  "When added to the home screen or installed as an app, the site opens like an app without the browser frame.": "ホーム画面に追加したときや、アプリとしてインストールしたときに、ブラウザの枠の無いアプリのように開きます。",
  "App name": "アプリ名",
  "Short name": "短い名前",
  "The name shown under the home screen icon. Keep it to about 12 characters.": "ホーム画面のアイコンの下に表示する名前です。12文字程度までにしてください。",
  "Icon": "アイコン",
  "A 512×512px square PNG is recommended. If not set, the home screen icon is used, then the favicon.": "512×512px の正方形のPNGをおすすめします。未設定のときはホーム画面のアイコンを、それも無ければファビコンを使います。",
  "Display mode": "表示モード",
  "Theme color": "テーマ色",
  "The title bar and status bar color when opened as an app.": "アプリとして開いたときの、タイトルバーやステータスバーの色です。",
  "Background color": "背景色",
  "The screen color shown while the app starts. It is also used around the icon.": "アプリを起動してから、ページが表示されるまでの画面の色です。アイコンの周りの余白にも使います。",
  "Styles and visibility settings for \"{label}\" on {used} elements will also be deleted (you can undo this).": "{used}個の要素に設定した、「{label}」用のスタイルと表示の設定も削除されます（「元に戻す」で戻せます）。",
  "Delete \"{label}\"?": "「{label}」を削除しますか？",
  "Styles for the added {names} ({used} elements) will be deleted.": "追加した{names}用のスタイル（{used}個の要素）を削除します。",
  "\"{name}\"": "「{name}」",
  "Reset breakpoints to the defaults?": "ブレークポイントを既定に戻しますか？",
  "Reset to defaults": "既定に戻す",
  "Breakpoints": "ブレークポイント",
  "Breakpoints let you change styles by screen width. Each one applies to screens at or below its width, and smaller ones take priority.\n\"Desktop\" is the width shown on the canvas. You can rename, add and remove breakpoints.": "ブレークポイントは、画面幅ごとにスタイルを変えるための区切りです。それぞれ、その幅以下の画面に適用され、小さい幅のものが優先されます。\n「パソコン」は、キャンバスに表示するときの幅です。名前を変えたり、追加・削除したりできます。",
  "Width shown on the canvas": "キャンバスで表示する幅",
  "Width": "幅",
  "Breakpoint name": "ブレークポイントの名前",
  "Applies to screens up to {maxWidth}px wide": "{maxWidth}px以下の画面に効きます",
  "Delete {label}": "{label}を削除",
  "You can add up to {MAX_BREAKPOINTS}": "{MAX_BREAKPOINTS}個まで追加できます",
  "Make sure it's a backup file saved from this editor.": "このエディタで保存したバックアップファイルか、確認してください。",
  "Couldn't load this file": "このファイルは読み込めませんでした",
  "No page or element data found. Choose a backup file saved from this editor.": "ページや要素の情報が見つかりません。このエディタで保存したバックアップファイルを選んでください。",
  "Not an editor data file": "編集データの形式ではありません",
  "Load the backup?": "バックアップを読み込みますか？",
  "Load": "読み込む",
  "Site name": "サイト名",
  "Browser tabs show \"Page name | Site name\".": "ブラウザのタブに、「ページ名 | サイト名」の形で表示されます。",
  "Site URL": "サイトURL",
  "Your published site's address (e.g. https://example.com). It is used for things like the URLs of share images.": "公開したサイトのアドレスです（例: https://example.com）。シェア用の画像のURLなどに使います。",
  "Custom language code": "カスタム言語コード",
  "Enter a language code (e.g. en-US or pt-BR). Your change has not been saved.": "言語コードを入力してください（例: en-US、pt-BR）。変更は保存されていません。",
  "Enter a language code (e.g. en-US or pt-BR).": "言語コードを入力してください（例: en-US、pt-BR）。",
  "The language this page is written in. \"Same as site\" uses the language from the site settings.": "このページの文章の言語です。「サイトと同じ」を選ぶと、サイトの設定の言語を使います。",
  "Same as site ({lang})": "サイトと同じ（{lang}）",
  "The language your pages are written in. Screen readers, browser translation and search engines treat the text as this language.": "ページの文章の言語です。読み上げやブラウザの翻訳、検索エンジンは、文章をこの言語として扱います。",
  "Data refresh interval (seconds)": "データの更新間隔（秒）",
  "Favicon (tab icon)": "ファビコン（タブのアイコン）",
  "A square PNG, SVG or ICO is recommended.": "正方形のPNG・SVG・ICOをおすすめします。",
  "Home screen icon": "ホーム画面アイコン",
  "The icon used when added to the home screen on iPhone or iPad (apple-touch-icon). A 180×180px PNG is recommended.": "iPhoneやiPadで「ホーム画面に追加」したときのアイコンです（apple-touch-icon）。180×180px のPNGをおすすめします。",
  "Default share image (OGP)": "デフォルトのシェア用画像（OGP）",
  "Used when a page doesn't set its own image. 1200×630px is recommended.": "ページで設定していないときに使います。1200×630px をおすすめします。",
  "Custom code (all pages)": "カスタムコード（全ページ共通）",
  "Head code": "head内コード",
  "Inserted into <head> on every page.": "すべてのページの <head> に挿入します。",
