  "[slug] page \"{name}\" doesn't fetch any data (in its \"When the page opens\" script, fetch one item using {slug})": "[slug]ページ「{name}」でデータを取得していません（ページを開いたときのスクリプトで、{slug} を使って1件のデータを取得してください）",
