  "For each day you edit, the server automatically keeps that day's final content. It keeps seven days, one per weekday, and saves a day's copy at the first save after the date changes.": "サーバーは、編集した日ごとに、その日の最後の内容を自動で残します。曜日ごとに7日分を残し、日付が変わって最初に保存したときに、前の日の内容を残します。",
