  "Return the published site to an earlier version, or bring your edits back to an earlier state.": "公開したサイトを前の版に戻したり、編集内容を前の状態に戻したりできます。",
  "Published site": "公開サイト",
  "Automatic backups of edits": "編集データの自動バックアップ",
  "Your current edits will be replaced with this file's content. Undo (⌘Z) brings back what you have now.": "いまの編集内容が、このファイルの内容に置き換わります。「元に戻す」（⌘Z）で、いまの内容に戻せます。",
  "Hosting": "公開先のホスティング",
  "The service that runs the exported site. It changes how pages that use external JSON are built.\nStandard: Vercel, Netlify, Node.js, etc. Pages are prebuilt and rebuilt at the refresh interval (ISR).\nCloudflare Workers: pages are rendered on every request, and fetched JSON is cached at Cloudflare for the refresh interval.": "書き出したサイトを動かすサービスです。外部のJSONを使うページの作り方が変わります。\n標準: Vercel・Netlify・Node.js など。ページを作り置きし、更新の間隔ごとに作り直します（ISR）。\nCloudflare Workers: アクセスのたびにページを描画し、取得したJSONを、更新の間隔の間はCloudflareのキャッシュに置きます。",
  "Standard (Vercel etc.)": "標準（Vercel など）",
  "How often pages that use external JSON fetch it again. In between, the prebuilt page (on Cloudflare, the fetched JSON) is reused to reduce server load. Set 0 to fetch on every request (always fresh, but heavier).": "外部のJSONを使うページが、JSONを取得し直す間隔です。その間は、作り置きのページ（Cloudflareでは取得済みのJSON）を使うため、サーバーの負荷を抑えられます。0にすると、アクセスのたびに取得します（常に最新ですが、負荷は大きくなります）。",
  "Restore from the server's automatic backups or from a published version": "サーバーの自動バックアップや、公開した版の編集内容に戻します",
  "Restore from history": "履歴から戻す",
  "Invalid repository (use the owner/name format): {repo}": "リポジトリの指定が正しくありません（owner/name の形で指定してください）: {repo}",
  "The test site and live site point to the same repository and branch. Use a different branch.": "テストのサイトと本番のサイトの公開先（リポジトリとブランチ）が同じです。別のブランチを指定してください",
  "Couldn't connect to GitHub. Contact your administrator.": "GitHubに接続できませんでした。管理者に問い合わせてください",
  "{step} failed ({status}). Writing to the site repository may not be allowed. Contact your administrator.": "{step}に失敗しました（{status}）。公開先のリポジトリへの書き込みが、許可されていない可能性があります。管理者に問い合わせてください",
  "Loading": "読み込み中",
