  "The service that runs the exported site, and how often pages that use external JSON fetch it again.": "書き出したサイトを動かすサービスと、外部のJSONを使うページがJSONを取得し直す間隔です。",
  "Unlock so the element can be moved and deleted on the canvas and in Layers again": "ロックを解除して、キャンバス・レイヤーで動かしたり削除したりできるようにします",
