  "Reset site": "サイトのリセット",
  "Removes all pages, elements and settings and returns the site to how it was when it was created. The published site doesn't change until you publish again.": "すべてのページ・要素・設定を消して、作成した直後の状態に戻します。公開したサイトは、もう一度公開するまで変わりません。",
