  "Drag the scale to move the playhead, click an empty spot on the bar below to add a keyframe, and drag ◆ to move it.": "上の目盛りをドラッグすると再生の位置が動き、下の帯の空いている所をクリックするとキーフレームを追加できます。◆ をドラッグすると、その時点を動かせます。",
