  "Click the timeline to add a keyframe.": "タイムラインをクリックすると、キーフレームを追加できます。",
  "This can't be split into fields. Write it as from / to / 0%–100% followed by { }.": "この書き方は、項目に分けられません。from / to / 0%〜100% の後に { } を続ける形で書いてください。",
  "Write the body of @keyframes (from / to / 0%–100%). Press the button again to go back to the fields.": "@keyframes の中身（from / to / 0%〜100%）を書きます。もう一度ボタンを押すと、項目での編集に戻ります。",
