  "The site name is still the default \"{siteName}\" (it's added after every page title)": "サイト名が初期値の「{siteName}」のままです（すべてのページのタイトルの後ろに付きます）",
  "The URL \"/{slug}\" of \"{name}\" is still the automatic one (a short word that describes the page reads better in search results and shares)": "「{name}」のURL「/{slug}」が自動で付けたままです（内容を表す短い英単語にすると、検索やシェアで伝わりやすくなります）",
  "The search and share title of \"{name}\" is still the automatic \"{title}\"": "「{name}」の検索・シェア用タイトルが自動で付けた「{title}」のままです",
  "{names} have the same search and share title \"{title}\" (they can't be told apart in search results or tabs)": "{names} の検索・シェア用タイトルが同じ「{title}」です（検索結果やタブで見分けられません）",
  "All sites: {files} files stored on the server{p2}": "全サイトの合計: サーバーに保存したファイル {files}件{p2}",
  "{count} of them ({size}) are scheduled for deletion and will be removed from the server {days} days after they were deleted.": "そのうち {count}件（{size}）は削除の予定で、削除してから{days}日後にサーバーから消えます。",
  "{count} deleted assets ({size}) remain on the server.": "そのうち、削除したアセット {count}件（{size}）が、サーバーに残っています。",
  "Until the weekly server-wide check finishes, only the files that sites use are counted.": "週に1回のサーバー全体の確認が終わるまでは、サイトで使っているファイルだけを数えています。",
  "The file stored on the server will be deleted in {days} days. It is kept if you undo before then or if another site uses it.": "サーバーに保存したファイルは、{days}日後に削除されます。それまでに元に戻すか、他のサイトで使っていれば残ります。",
  "The file stored on the server is kept, not deleted.": "サーバーに保存したファイルは、削除されずに残ります。",
  "Used in {used} places. It will also be removed from the elements that use it. ": "{used}か所で使っています。使っている要素からも外して、削除します。",
  "Usage (all sites)": "使用量（全サイト）",
