  "The comment you are editing has been deleted.": "編集するコメントは削除されています",
  "The discussion you are replying to has been deleted.": "返信先のスレッドは削除されています",
  "This thread has been deleted. Your draft remains until you close it, so copy it if you need it.": "このスレッドは削除されています。入力中の文章は閉じるまで残るため、必要ならコピーしてください。",
  "List display item (changes for each entry)": "リスト表示の項目（1件ずつ変わる）",
  "Turn into list display": "リスト表示にする",
  "To show data, attach \"Set variable ［］ to ［value］\" under \"Fetch data from ［URL］ as ［name］\" to pull out what you need (this runs when the page opens). Then select a variable that holds a list in a List display element's settings to show each item.": "データを表示するには、「［URL］のデータを取得して［名前］とする」の下に「［値］を変数［］とする」をつなげて、必要な値を取り出します（ページを開いたときに実行されます）。リストの入った変数を、リスト表示の設定で選ぶと、1件ずつ並べて表示します。",
  "Create a list display using this box as a template for each data item": "このボックスをお手本にして、データの件数分くり返すリスト表示を作ります",
  "List display": "リスト表示",
  "The first item in the list display is the template card. Type \"{\" in its text and pick a field to apply it to every card.\nSort and filter with the \"Sort\" and \"Filter\" script actions.": "リスト表示の1つ目が、お手本のカードです。カードの中の文字で「{」を入力して項目を選ぶと、すべてのカードに反映されます。\n並べ替えや絞り込みは、スクリプトの「並べ替える」「絞り込む」で行います。",
  "List · set after the page opens": "リスト · ページを開いてから値が決まる",
  "List · {length} sample items": "リスト · 見本{length}件",
  "Outer list display item · {count} sample items": "外側のリスト表示の項目 · 見本{count}件",
  "List to display": "表示するリスト",
  "{p1} (not a list)": "{p1}（リストになっていません）",
  "Store data in a variable or split text into a list with a script, and it will appear here": "スクリプトでデータを変数に入れるか、文字列を分解してリストにすると、ここで選べるようになります",
  "Create a list with a script": "スクリプトでリストを作る",
  "Choose the list to display in the list display settings": "リスト表示の設定で、表示するリストを選んでください",
  "List · {length} items (can be shown in a list display)": "リスト・{length}要素（リスト表示で並べられます）",
  "No lists": "リストがありません",
  "Search or enter a list path": "リスト名・位置を検索または入力",
  "Use entered path: {path}": "入力した位置を使用: {path}",
  "Enter a path or index": "位置または添字を入力",
  "Index (0-based) or full path": "添字（0始まり）または位置",
  "Enter a path": "位置を入力",
  "Use path": "使用する",

  "Lists inside variables": "変数の中のリスト",
  "Use {{field}} in each list display item (sample: {sample})": "リスト表示の項目では {{field}} として使えます（見本: {sample}）",
  "How this combines with other filters on the same list": "同じリストのほかの絞り込みとのつなぎ方",
  "This loop contains actions or variable references that cannot run before the page is served. Check the nested blocks.": "このくり返しには、ページを配信する前には実行できない操作か、変数の参照が含まれています。中のブロックを確認してください。",
  "Clear {which} on list {array}": "リスト{array}の{which}を解除する",
  "Sort list {array} by {field} {dir}": "リスト{array}を{field}の{dir}に並べ替える",
  "Filter list {array} to items where {field} {cond}": "リスト{array}を{field}が{cond}",
  "{negation} {op} named {value}": "{value}という{op}{negation}",
  "For each item in list {array}": "リスト{array}の要素ごとにくり返す",
  "Showing the saved sample.": "保存した見本を表示しています。",
  "The sample saves only the first 20 items of each list. To view all items, use Fetch again in the top-right corner.": "見本には、リストの先頭の20件だけを保存しています。すべてを見るには、右上の「取得し直す」で取得し直してください。",
  "No list found": "リストが見つかりません",
  "Overwrite an existing variable": "既存の変数を上書き",
  "For each item in list ［］": "リスト［］の要素ごとにくり返す",
  "List display \"{name2}\" in \"{name}\" has no list selected (it won't be output)": "「{name}」のリスト表示「{name2}」に表示するリストが選ばれていません（出力されません）",
  "{head}Filter list {p2} to items where {conds}": "{head}リスト{p2}を {conds} ものに絞り込む",
  "Clear filter {no} on list {p1}": "リスト{p1}の絞り込み{no}を解除する",
  "Clear all filters on list {p1}": "リスト{p1}のすべての絞り込みを解除する",
  "Sort list {array} by {field}, descending": "リスト{array}を {field} の降順に並べ替える",
  "Sort list {array} by {field}, ascending": "リスト{array}を {field} の昇順に並べ替える",
  "Split \"{source}\" by \"{p2}\" into a list {p3}": "「{source}」を「{p2}」で分解してリスト{p3}とする",
  "For each item in list {p1}…": "リスト{p1}の要素ごとにくり返す…",
  "Back": "戻る",
  "First, select the element you want to work on by clicking it on the canvas or in Layers.": "まず、操作したい要素をキャンバスかレイヤーでクリックして選んでください。",
  "First, click a text element (text, heading or button) to select it.": "まず、文字の要素（テキスト・見出し・ボタン）をクリックして選んでください。",
  "First, click an image to select it.": "まず、画像をクリックして選んでください。",
  "First, select the box (parent) that contains the elements. If a child is selected, press ⇧Enter to select its parent.": "まず、要素を入れているボックス（親）を選んでください。中の要素を選んでいるときは、⇧Enter で親を選べます。",
