  "New menu": "新メニュー",
  "Opening hours": "営業時間",
  "Summer break": "夏季休業",
  "The first is the template": "1つ目がお手本",
  "The rest follow automatically": "残りは自動で並ぶ",
  "A page for each data item": "データの1件ごとにページができる",
  "Edit the main component": "マスターを直す",
