  "Choose **After** next to Insert into in the Add tab, and new elements go right after the selected element (at the same level). Switch back to **Inside** to put them inside a selected box.": "「追加」タブの「挿入先」で「**後ろへ**」を選ぶと、選んだ要素のすぐ後ろ（同じ階層）に入ります。「**中へ**」に戻すと、ボックスを選んでいるときは、その中に入ります。",
  "sibling": "兄弟",
  "same level": "同じ階層",
  "The setting applies not only to adding elements but also to **pasting (⌘V)** and adding images or components. You aren't asked every time; the last choice made in this browser is used.": "この切り替えは、部品の追加だけでなく、**貼り付け（⌘V）**や、画像・コンポーネントの追加にも適用されます。毎回は確認せず、このブラウザで最後に選んだほうを使います。",
  "When the selected element can't contain others, like text or an image, new elements always go after it.": "文字や画像など、中に要素を入れられない要素を選んでいるときは、どちらを選んでいても後ろに入ります。",
  "Switch between Inside and After here.": "ここで「中へ」と「後ろへ」を切り替えます。",
  "I want to return the live site to an earlier version (rollback)": "公開したサイトを前の状態に戻したい（ロールバック）",
  "Open **Publish history & rollback** in the Publish dialog (or History in the \"…\" menu) and click **Restore site** on the version you want.": "「公開」の画面の「**公開履歴・ロールバック**」か、「…」メニューの「履歴」で、戻したい版の「**サイトを戻す**」を押します。",
  "rollback": "ロールバック",
  "publish history": "公開履歴",
  "earlier version": "前の版",
  "What it restores": "戻るもの",
  "The published site. The chosen version is published again as a new version.": "公開しているサイト。選んだ版と同じ内容を、新しい公開として追加します",
  "The editor's content, as it was when that version was published (⌘Z undoes it).": "エディタの編集内容。その版を公開した時点の内容を、エディタに読み込みます（⌘Z で戻せます）",
  "\"Restore site\" alone leaves the editor's content as it is, and the next publish overwrites the site with it. **To bring back the edits too, also use \"Restore edits\"**.": "「サイトを戻す」だけでは、エディタの編集内容は変わりません。そのまま次に公開すると、いまの編集内容で上書きされます。**編集内容も戻すときは、「編集内容を復元」も使います**。",
  "It takes as long as a normal publish to go live (when the hosting service finishes the build).": "反映されるまでの時間は、通常の公開と同じです（ホスティングの側のビルドが終わると反映されます）。",
  "Click Publish, then open \"Publish history & rollback\" at the bottom.": "「公開」を押し、下の「公開履歴・ロールバック」を開きます。",
  "I deleted or broke something and want yesterday's version back": "間違えて消した・壊した編集内容を、前の日の状態に戻したい",
  "Open **History** in the \"…\" menu, go to \"Automatic backups of edits\" and click \"Restore this\" on the day you want. **⌘Z brings back the current content** afterwards.": "「…」メニューの「**履歴**」の「編集データの自動バックアップ」で、戻したい日の「この内容に戻す」を押します。戻した後も、**⌘Z でいまの内容に戻せます**。",
  "previous day": "前の日",
