  "How does test publishing work?": "テスト公開はどんなしくみ？",
  "Test publishing commits to **a separate branch of the same repository** (preview by default). Vercel, Cloudflare and others automatically publish non-production branches at a **preview URL**.": "テスト公開では、本番と**同じリポジトリの別のブランチ**（既定は preview）にコミットします。Vercel や Cloudflare などは、本番以外のブランチを、**プレビュー用のURL**で自動的に公開します。",
  "branch": "ブランチ",
