  "Pages are rendered on every request, and fetched JSON is cached at Cloudflare for the refresh interval": "アクセスのたびにページを描画し、取得したJSONを更新間隔のあいだCloudflareのキャッシュに置く",
  "If you publish to Cloudflare Workers with \"Standard\", prebuilt pages are **never rebuilt** (the cache that ISR needs isn't set up there).": "Cloudflare Workers に「標準」のまま公開すると、作り置きのページが**いつまでも作り直されません**（ISR に必要なキャッシュの設定が無いため）。",
  "With a refresh interval of 0, every host fetches the latest data on every request.": "更新の間隔を 0 にすると、どのホスティングでも、アクセスのたびに最新のデータを取得します。",
