  "Hover over Save at the bottom right to see who made the latest change and who edited in the last 10 minutes. Hover over Publish to see when the site was last published and by whom.": "右下の「保存」にポインターを乗せると、最後に変更した人と、直近10分に変更した人が表示されます。「公開」に乗せると、最後に公開した時刻と人が表示されます。",
