  "Turn on comment mode with the speech-bubble button in the top bar (or the C key), then click an element on the canvas to comment on it.": "上のバーの吹き出しのボタン（か C キー）でコメントモードにし、キャンバスの要素をクリックすると、コメントを付けられます。",
