  "The right panel lists the comments on this page (or all pages). Click one to jump to it.": "右のパネルに、このページ（かすべてのページ）のコメントの一覧が表示されます。押すと、そのコメントの場所へ移ります。",
  "Comments aren't part of the published site and aren't affected by Undo. You can only edit or delete comments you wrote.": "コメントは公開するサイトには含まれず、「元に戻す」の対象にもなりません。編集や削除ができるのは、自分が書いたコメントだけです。",
