  "Set the state to Hover, set Scale to 105%, and add a “state change” motion to make a button or card that grows smoothly when the pointer is over it.": "状態を「ホバー」にして「拡大」を105%にし、モーションで「状態の変化」を付けると、ポインターを乗せたときに、ふわっと大きくなるボタンやカードを作れます。",
  "A move in % is relative to the element's own size (-50% moves it left by half its width).": "移動を%で指定すると、要素自身の大きさに対する割合になります（-50%なら、自分の幅の半分だけ左へ動きます）。",
  "Choose Transform from the + in Effects.": "「エフェクト」の「＋」から「変形」を選びます。",
