  "Select the field. Set its type, initial value, placeholder and whether it's required under Form field on the Settings tab, and colors such as the checkbox or slider color under Input on the Style tab.": "入力欄を選び、右のパネルの「設定」の「フォーム部品」で、種類・初期値・案内文・必須などを変えます。チェックやスライダーの色などは、「スタイル」の「入力欄」で変えます。",
  "slider": "スライダー",
  "placeholder": "プレースホルダー",
  "The initial value, placeholder, label and options can contain {variables}, such as fetched data or the value of another field ({ID}).": "初期値・案内文・表示テキスト・選択肢には、{変数} を書けます。取得したデータや、他の入力欄の値（{ID}）を入れられます。",
  "Number, slider and date fields have a minimum, maximum and step; text fields have a maximum length. A Required field can't be submitted empty.": "数値・スライダー・日付では、最小・最大・刻みを、文字の欄では、最大の文字数を決められます。「必須」にすると、空のままでは送信できません。",
  "When a script's If compares a checkbox's value, you can pick On or Off.": "スクリプトの「もし」でチェックボックスの値を比べるときは、「オン」か「オフ」を選べます。",
  "I want to set up inputs, checkboxes, switches and sliders": "入力欄・チェックボックス・スイッチ・スライダーを設定したい",
  "For checkboxes and switches, {ID} is true when checked and false when not. When a script's If compares it, you can pick On or Off.": "チェックボックスとスイッチの {ID} は、チェックしているときは true、していないときは false です。スクリプトの「もし」で比べるときは、「オン」か「オフ」を選べます。",
  "Radio buttons with the same Group allow only one choice. {group name} is the chosen button's value (its label), and {ID} is true or false depending on whether that button is chosen.": "ラジオボタンは、「グループ」を同じにすると、1つだけを選べます。{グループ名} が、選んだボタンの値（表示テキスト）になり、{ID} が、そのボタンを選んでいるかどうかを表す true / false になります。",
  "Under Show advanced in Find a variable, you can also pick whether a field is disabled ({ID.disabled}), its length ({ID.length}) and the chosen number ({ID.index}). The script block “Set ［field］ to ［enabled / disabled］” switches whether it is disabled.": "「変数を探す」の「詳細を表示」で、無効かどうか（{ID.disabled}）・文字数（{ID.length}）・選んだ番号（{ID.index}）も選べます。無効かどうかは、スクリプトの「［入力欄］を［有効にする / 無効にする］」で切り替えられます。",
